    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the most common tumor suppressor gene mutation in human cancers?', '["RAS", "p53", "MYC", "HER2"]', 1, 'p53 regulates cell cycle and apoptosis. (Schwartz''s Ch. 10)'),
    (v_topic_id, '2: "Oncogenes" typically require a mutation in ____ allele(s) to promote cancer.', '["One (Gain-of-function)", "Both (Loss-of-function)", "Three", "None"]', 0, 'Contrast with tumor suppressors which follow the "two-hit" hypothesis. (de Virgilio Ch. 18)'),
    (v_topic_id, '3: The "TNM" staging system - what does "N" stand for?', '["Nerve invasion", "Regional Lymph Nodes", "Neovascularization", "None"]', 1, 'Stands for Tumor, Node, Metastasis. (Mont Reid Ch. 11)'),
    (v_topic_id, '4: "Adjuvant" therapy is defined as treatment given:', '["Before the primary surgery", "After the primary surgery to eliminate micrometastases", "During surgery", "Instead of surgery"]', 1, 'Improves disease-free survival. (Schwartz''s Ch. 10)'),
    (v_topic_id, '5: "Neoadjuvant" therapy is given "before" surgery primarily to:', '["Check for drug allergies", "Shrink the tumor and increase resectability", "Wait for the surgeon to return", "None"]', 1, 'Common in breast and rectal cancers. (de Virgilio Ch. 18)'),
    (v_topic_id, '6: Which biopsy technique is preferred for a suspected "Soft Tissue Sarcoma"?', '["FNA", "Core Needle Biopsy (Longitudinal)", "Excisional biopsy", "None"]', 1, 'Preserves tissue architecture for grading; longitudinal orientation prevents future contamination. (Mont Reid Ch. 11)'),
    (v_topic_id, '7: An "Incisional" biopsy is indicated when the mass is large (> 5 cm) and the goal is:', '["Definitive removal", "Tissue diagnosis before definitive plan", "Cosmetic", "None"]', 1, 'Avoid excising the whole mass if it requires a complex reconstruction. (Schwartz''s Ch. 10)'),
    (v_topic_id, '8: "Breslow Depth" in Melanoma is a measurement of the tumor thickness from the granular layer of the epidermis to:', '["The bone", "The deepest tumor cell", "The basement membrane", "None"]', 1, 'The most important prognostic factor in Stage I/II melanoma. (de Virgilio Ch. 19)'),
    (v_topic_id, '9: "Sentinel Lymph Node Biopsy" (SLNB) in melanoma is generally indicated for tumors with a Breslow depth >= ____ mm.', '["0.5", "0.8 to 1.0", "4.0", "None"]', 1, 'Standard for staging clinically negative nodes. (Mont Reid Ch. 11)'),
    (v_topic_id, '10: A "Positive" surgical margin means:', '["The patient is cured", "Tumor is present at the edge of the specimen", "No tumor found", "None"]', 1, 'Increases risk of local recurrence; usually requires re-excision. (Schwartz''s Ch. 10)'),
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '51: "Cancer" - Warburg effect?', '["Preferential use of glycolysis (fermentation) even with oxygen", "True", "Both", "None"]', 2, 'Metabolic hallmark. (Schwartz''s Ch. 10)'),
