    (v_topic_id, '53: "Cancer" - Angiogenesis?', '["VEGF-mediated new blood vessel growth", "Both", "None", "None"]', 0, 'Essential for growth > 2mm. (Mont Reid Ch. 11)'),
    (v_topic_id, '54: "BRCA1" - Chromosome?', '["13", "17", "21", "None"]', 1, 'Genetics. (Schwartz''s Ch. 17)'),
    (v_topic_id, '55: "BRCA2" - Chromosome?', '["13", "17", "X", "None"]', 0, 'Genetics. (de Virgilio Ch. 18)'),
