    (v_topic_id, '59: "Lynch" - most common extra-colonic cancer?', '["Gastric", "Endometrial", "Bladder", "None"]', 1, 'Requires screening. (Mont Reid Ch. 11)'),
    (v_topic_id, '60: "Sarcoma" - staging?', '["TNM + Grade (G1-G3)", "Both", "None", "None"]', 0, 'Grade is critical. (Schwartz''s Ch. 10)'),
    (v_topic_id, '61: "Sarcoma" - amputation?', '["Rarely needed (Limb-salvage is 95%)", "True", "Both", "None"]', 2, 'Trend. (de Virgilio Ch. 19)'),
