    (v_topic_id, '68: "Gastric" - Lauren classification?', '["Intestinal vs Diffuse", "Both", "None", "None"]', 0, 'Histology. (Mont Reid Ch. 11)'),
    (v_topic_id, '69: "Gastric" - Diffuse type?', '["Linitis plastica / Signet ring cells", "Poorer prognosis", "Both", "None"]', 2, 'Histology. (Schwartz''s Ch. 26)'),
    (v_topic_id, '70: "Gastric" - Lymphadenectomy?', '["D1 (perigastric) vs D2 (vessel-based)", "D2 standard in East, gaining in West", "Both", "None"]', 2, 'Surgery. (de Virgilio Ch. 14)'),
