    (v_topic_id, '72: "Pancreas" - Adjuvant chemo?', '["FOLFIRINOX or Gemcitabine", "Both", "None", "None"]', 0, 'Standard. (Schwartz''s Ch. 33)'),
    (v_topic_id, '73: "Colon" - T3?', '["Invades through muscularis propria into subserosa", "Both", "None", "None"]', 0, 'Staging. (de Virgilio Ch. 11)'),
