    (v_topic_id, '79: "Radiation" - Early side effect?', '["Skin erythema / fatigue", "Both", "None", "None"]', 0, 'Side effect. (de Virgilio Ch. 18)'),
    (v_topic_id, '80: "Radiation" - Late side effect?', '["Fibrosis / Secondary malignancy (Sarcoma)", "Both", "None", "None"]', 0, 'Side effect. (Mont Reid Ch. 11)'),
    (v_topic_id, '81: "Chemotherapy" - 5-FU side effect?', '["Diarrhea / Hand-foot syndrome", "Both", "None", "None"]', 0, 'Side effect. (Schwartz''s Ch. 10)'),
    (v_topic_id, '82: "Chemotherapy" - Cisplatin side effect?', '["Ototoxicity / Nephrotoxicity", "Both", "None", "None"]', 0, 'Side effect. (de Virgilio Ch. 18)'),
