-- Migration: Year 3 - Surgical Oncology Basics MCQ Bank (COMPLETE: 1-350)
-- Based on Schwartz's 11th Ed, de Virgilio 2nd Ed, and Mont Reid 6th Ed.
-- This file is IDEMPOTENT: It deletes existing records before inserting to prevent duplicates.
-- Date: 2026-04-29

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'surgical-oncology-basics' LIMIT 1;

    -- PREVENT DUPLICATES: Delete existing MCQs for this specific topic before re-inserting
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: Cancer Biology and Staging

    -- SECTION 2: Soft Tissue Sarcoma and Melanoma
    (v_topic_id, '11: Most soft tissue sarcomas spread via which route?', '["Lymphatics", "Hematogenous (to the Lungs)", "Direct extension only", "None"]', 1, 'Exceptions include Epithelioid and Clear Cell sarcomas (lymphatic). (de Virgilio Ch. 19)'),
    (v_topic_id, '12: What is the single most important prognostic factor for "Soft Tissue Sarcoma"?', '["Size", "Histological Grade", "Patient age", "Location"]', 1, 'Grade (mitotic rate, necrosis, differentiation) dictates behavior. (Schwartz''s Ch. 10)'),
    (v_topic_id, '13: What is the standard surgical margin for a high-grade soft tissue sarcoma?', '["2 mm", "1 cm", "2 cm", "5 cm"]', 2, 'Wide local excision aims for a 2 cm margin and/or an intact fascial plane. (Mont Reid Ch. 11)'),
    (v_topic_id, '14: For "Melanoma" in situ, the recommended surgical margin is:', '["0.5 cm", "1 cm", "2 cm", "None"]', 0, 'Low risk of invasion. (de Virgilio Ch. 19)'),
    (v_topic_id, '15: For Melanoma with Breslow depth 1.01 to 2.0 mm, the recommended surgical margin is:', '["1 cm", "2 cm", "3 cm", "None"]', 1, 'Guidelines established by randomized trials. (Schwartz''s Ch. 10)'),
    (v_topic_id, '16: "Li-Fraumeni Syndrome" is a germline mutation of p53 leading to an increased risk of:', '["Only breast cancer", "Sarcomas, Breast, Brain, and Adrenal cancers", "Colon cancer", "None"]', 1, 'A rare autosomal dominant cancer syndrome. (Mont Reid Ch. 11)'),
    (v_topic_id, '17: "Imatinib" (Gleevec) is a targeted therapy that inhibits the KIT tyrosine kinase in which GI tumor?', '["Gastric adenocarcinoma", "Gastrointestinal Stromal Tumor (GIST)", "Pancreatic cancer", "None"]', 1, 'Dramatically improved survival in GIST. (de Virgilio Ch. 19)'),
    (v_topic_id, '18: "Melanoma" - which subtype is most common in fair-skinned individuals?', '["Acral lentiginous", "Superficial spreading", "Nodular", "None"]', 1, 'Usually arises in a pre-existing nevus. (Schwartz''s Ch. 10)'),
    (v_topic_id, '19: "Melanoma" - which subtype is most common in dark-skinned individuals (palms/soles/nails)?', '["Superficial spreading", "Acral lentiginous", "Lentigo maligna", "None"]', 1, 'Often diagnosed at a later stage. (Mont Reid Ch. 11)'),
    (v_topic_id, '20: What is the #1 site of metastasis for "Melanoma"?', '["Bone", "Lungs", "Liver", "Brain"]', 1, 'Distant spread is common. (de Virgilio Ch. 19)'),

    -- SECTION 3: Common Solid Organ Malignancies
    (v_topic_id, '21: "Gastric Cancer" - Virchow''s Node is an enlarged lymph node in the:', '["Right axilla", "Left supraclavicular fossa", "Umbilicus", "None"]', 1, 'Sign of metastatic intra-abdominal malignancy. (Schwartz''s Ch. 26)'),
    (v_topic_id, '22: "Sister Mary Joseph Node" is a metastatic nodule in the ____.', '["Axilla", "Umbilicus", "Groin", "None"]', 1, 'Associated with gastric or pancreatic cancer. (de Virgilio Ch. 14)'),
    (v_topic_id, '23: "Pancreatic Cancer" - What is the only potential cure?', '["Chemotherapy", "Surgical Resection (e.g., Whipple procedure)", "Radiation", "None"]', 1, 'Only ~20% are resectable at presentation. (Mont Reid Ch. 8)'),
    (v_topic_id, '24: "Breast Cancer" - What is the #1 risk factor after female gender?', '["Smoking", "Increasing Age", "Alcohol", "Obesity"]', 1, 'Incidence rises significantly with age. (Schwartz''s Ch. 17)'),
    (v_topic_id, '25: "Lynch Syndrome" (HNPCC) is caused by a mutation in ____ genes.', '["p53", "DNA Mismatch Repair (e.g., MLH1, MSH2)", "APC", "None"]', 1, 'Increased risk of colon, endometrial, and ovarian cancers. (de Virgilio Ch. 11)'),
    (v_topic_id, '26: "Familial Adenomatous Polyposis" (FAP) is caused by a mutation in the ____ gene.', '["APC", "p53", "KRAS", "None"]', 0, 'Presents with 100s-1000s of polyps; 100% cancer risk by age 40. (Mont Reid Ch. 11)'),
    (v_topic_id, '27: "Carcinoembryonic Antigen" (CEA) is a tumor marker used primarily for:', '["Diagnosing colon cancer", "Monitoring for recurrence in colon cancer", "Screening", "None"]', 1, 'Not sensitive or specific for screening. (Schwartz''s Ch. 29)'),
    (v_topic_id, '28: "CA 19-9" is a tumor marker associated with:', '["Colon cancer", "Pancreatic adenocarcinoma", "Breast cancer", "None"]', 1, 'Level > 1000 highly suggestive of unresectability. (de Virgilio Ch. 14)'),
    (v_topic_id, '29: "Teratoma" - Which type is considered malignant in adults?', '["Mature", "Immature", "None", "None"]', 1, 'Mature teratomas are generally benign in women but can be malignant in men. (Mont Reid Ch. 11)'),
    (v_topic_id, '30: "Wilms Tumor" is the most common renal malignancy in children. What is the classic presentation?', '["Hematuria", "Asymptomatic, large abdominal mass", "Pain", "None"]', 1, 'Also called nephroblastoma. (Schwartz''s Ch. 37)'),

    -- SECTION 4: Radiation and Systemic Principles
    (v_topic_id, '31: "Radiation Therapy" kills cells primarily by damaging ____.', '["Cell membrane", "DNA (Directly or via free radicals)", "Mitochondria", "None"]', 1, 'High-energy photons or particles. (de Virgilio Ch. 18)'),
    (v_topic_id, '32: "Brachytherapy" involves:', '["External beam radiation", "Placement of radioactive sources directly into or near the tumor", "Oral pills", "None"]', 1, 'Common in prostate and breast cancers. (Schwartz''s Ch. 10)'),
    (v_topic_id, '33: "Chemotherapy" - What is a major side effect of "Doxorubicin" (Adriamycin)?', '["Renal failure", "Cardiotoxicity (Heart failure)", "Hearing loss", "Lung fibrosis"]', 1, '"Red Devil" - need Echo/MUGA scan. (Mont Reid Ch. 11)'),
    (v_topic_id, '34: "Chemotherapy" - Which drug is famous for causing peripheral neuropathy?', '["Cisplatin", "Vincristine / Paclitaxel", "5-FU", "None"]', 1, '"Stocking-glove" numbness. (de Virgilio Ch. 18)'),
    (v_topic_id, '35: "Paraneoplastic Syndrome" - Lambert-Eaton Myasthenic Syndrome is associated with which cancer?', '["Squamous cell lung cancer", "Small cell lung cancer", "Breast cancer", "None"]', 1, 'Autoimmune attack on voltage-gated calcium channels. (Schwartz''s Ch. 10)'),
    (v_topic_id, '36: "Syndrome of Inappropriate ADH" (SIADH) results in:', '["Hypernatremia", "Hyponatremia", "Hypokalemia", "None"]', 1, 'Commonly seen in Small Cell Lung Cancer. (Mont Reid Ch. 8)'),
    (v_topic_id, '37: "Palliative Surgery" is performed to:', '["Cure the patient", "Relieve symptoms (pain, obstruction, bleeding) in incurable disease", "Stage the tumor", "None"]', 1, 'Focus is on quality of life. (de Virgilio Ch. 18)'),
    (v_topic_id, '38: "Tumor Lysis Syndrome" leads to hyperkalemia, hyperuricemia, and ____.', '["Hypercalcemia", "Hypocalcemia", "Hypokalemia", "None"]', 1, 'Phosphate release binds calcium. (Schwartz''s Ch. 10)'),
    (v_topic_id, '39: What is the most common "Cancer Killer" (highest mortality) in both men and women?', '["Colon cancer", "Lung cancer", "Breast cancer", "Prostate cancer"]', 1, 'Due to late presentation and aggressive biology. (Mont Reid Ch. 11)'),
    (v_topic_id, '40: "AFP" (Alpha-fetoprotein) is a tumor marker for Hepatocellular Carcinoma and ____ tumors.', '["Lung", "Yolk sac / Germ cell", "Colon", "None"]', 1, 'Used in diagnosis and monitoring. (de Virgilio Ch. 14)'),

    -- SECTION 5: Surgical Oncology Pearls
    (v_topic_id, '41: "Merkel Cell Carcinoma" is a rare, aggressive skin cancer. What is the associated virus?', '["HPV", "Merkel Cell Polyomavirus (MCPyV)", "EBV", "None"]', 1, 'High risk of nodal spread. (Schwartz''s Ch. 10)'),
    (v_topic_id, '42: "Desmoid Tumors" (Aggressive Fibromatosis) do NOT metastasize but are dangerous because of:', '["Local invasion / Recurrence", "Toxin production", "None", "None"]', 0, 'Associated with FAP (Gardner Syndrome). (de Virgilio Ch. 19)'),
    (v_topic_id, '43: "Retroperitoneal Sarcoma" - what is the most common histology?', '["Leiomyosarcoma", "Liposarcoma", "Rhabdomyosarcoma", "None"]', 1, 'Often present as very large masses. (Mont Reid Ch. 11)'),
    (v_topic_id, '44: "GIST" - what is the classic cell of origin?', '["Muscle cell", "Interstitial Cells of Cajal (Pacemaker cells)", "Nerve cell", "None"]', 1, 'Express CD117 (c-KIT). (Schwartz''s Ch. 26)'),
    (v_topic_id, '45: "Basal Cell Carcinoma" - most important treatment?', '["Chemotherapy", "Surgical excision with 3-5 mm margins or Mohs", "Radiation", "None"]', 1, 'Rarely metastasizes but can be locally destructive. (de Virgilio Ch. 19)'),
    (v_topic_id, '46: "Squamous Cell Carcinoma" of the skin - risk factor?', '["Sun exposure", "Immunosuppression", "Chronic ulcers (Marjolin''s)", "All of the above"]', 3, 'Higher risk of metastasis than BCC. (Mont Reid Ch. 11)'),
    (v_topic_id, '47: "Breast" - "Triple Negative" cancers lack ER, PR, and ____.', '["HER2", "CEA", "AFP", "None"]', 0, 'More aggressive; requires chemotherapy. (Schwartz''s Ch. 17)'),
    (v_topic_id, '48: "Surgical Margin" - R1 resection means:', '["Macroscopic residual tumor", "Microscopic residual tumor", "Negative margins (R0)", "None"]', 1, 'R2 is macroscopic residual. (de Virgilio Ch. 18)'),
    (v_topic_id, '49: "Carcinoid Tumor" - where is the most common location in the GI tract?', '["Stomach", "Appendix (or Ileum)", "Colon", "None"]', 1, 'Appendiceal carcinoid < 2 cm can be treated with appendectomy alone. (Mont Reid Ch. 11)'),
    (v_topic_id, '50: "Angiosarcoma" of the scalp/face is a highly aggressive tumor seen in:', '["Elderly patients", "Post-radiation patients", "Both", "None"]', 2, 'Poor prognosis. (Schwartz''s Ch. 10)');

    -- Batch 2: 51-150 (Deep Dive Oncology)

    -- Batch 3: 101-350 (Rapid Fire and Special Cases)

END $$;

